<script setup>
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRouter } from 'vue-router'
import quizText from '../data/mockQuiz.json?raw'
import I18nManager from '@/i18n/manager'
import { useQuizSession } from '@/composables/useQuizSession'
const quiz = JSON.parse(quizText)
const { t } = useI18n(); const router = useRouter(); const { reset } = useQuizSession(); const open = ref(0)
const correct = computed(() => quiz.questions.filter(q => q.status === 'correct').length); const incorrect = computed(() => quiz.questions.filter(q => q.status === 'incorrect').length); const unanswered = computed(() => quiz.questions.filter(q => q.status === 'unanswered').length)
function statusText(status) { return t(`result.status.${status}`) }; function newQuiz() { reset(); router.push(I18nManager.i18nRoute({ name: 'home' })) }
</script>
<template><main class="result-page"><section class="result-hero"><div><p class="eyebrow">{{ t('result.eyebrow') }}</p><h1>{{ t('result.title') }}</h1><p>{{ t('result.subtitle', { correct }) }}</p></div><div class="score"><span>{{ quiz.totalScore }}<small>/{{ quiz.maxScore }}</small></span><p>{{ t('result.score') }}</p></div></section><section class="summary"><article class="correct"><b>{{ correct }}</b><span>{{ t('result.status.correct') }}</span></article><article class="incorrect"><b>{{ incorrect }}</b><span>{{ t('result.status.incorrect') }}</span></article><article class="unanswered"><b>{{ unanswered }}</b><span>{{ t('result.status.unanswered') }}</span></article><article class="time"><b>02:56</b><span>{{ t('result.totalTime') }}</span></article></section><section class="review"><div class="review-heading"><div><p class="eyebrow">{{ t('result.reviewEyebrow') }}</p><h2>{{ t('result.reviewTitle') }}</h2></div><button class="new-quiz" @click="newQuiz">{{ t('result.newQuiz') }} →</button></div><article v-for="(item,index) in quiz.questions" :key="item.id" class="answer-card" :class="item.status"><button class="answer-top" @click="open = open === index ? -1 : index"><span class="number">{{ item.id }}</span><span class="prompt">{{ item.prompt }}</span><span class="badge">{{ statusText(item.status) }}</span><span class="chevron">{{ open === index ? '−' : '+' }}</span></button><div v-if="open === index" class="answer-detail"><div class="metric"><span>{{ t('result.questionScore') }}</span><strong>{{ item.score }}/2</strong></div><div class="metric"><span>{{ t('result.time') }}</span><strong>{{ item.durationSeconds ? `00:${item.durationSeconds}` : '—' }}</strong></div><div class="detail-grid"><div><span>{{ t('result.yourAnswer') }}</span><p>{{ item.status === 'unanswered' ? t('result.noAnswer') : item.studentAnswerLabel }}</p></div><div><span>{{ t('result.expectedAnswer') }}</span><p>{{ item.expectedAnswer }}</p></div></div><div class="feedback"><span>✦</span><p>{{ item.feedback }}</p></div></div></article></section></main></template>
<style>
.result-page { max-width: 1080px; margin: auto; padding: 3.5rem 5vw 6rem; }.result-hero { min-height: 265px; padding: clamp(1.8rem,5vw,3.4rem); display: flex; align-items: center; justify-content: space-between; gap: 2rem; border-radius: 28px; background: #E7F3EA; }.eyebrow { color: #347158; font-size: .75rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }.result-hero h1,.review h2 { margin: .55rem 0 .75rem; color: #1F5B45; font: 700 clamp(2rem,4vw,3.3rem) Lora,serif; }.result-hero p:not(.eyebrow) { max-width: 540px; color: #52705D; line-height: 1.5; }.score { width: 160px; height: 160px; flex: 0 0 auto; display: grid; place-content: center; border: 9px solid #A8C7B4; border-top-color: #1F5B45; border-radius: 50%; color: #1F5B45; background: #FAF8F1; text-align: center; transform: rotate(25deg); }.score > * { transform: rotate(-25deg); }.score span { font-size: 2.8rem; font-weight: 800; line-height: 1; }.score small { font-size: 1.2rem; }.score p { margin-top: .25rem; font-size: .72rem; font-weight: 800; }.summary { display: grid; grid-template-columns: repeat(4,1fr); gap: 1rem; margin: 1.5rem 0 5rem; }.summary article { min-height: 100px; padding: 1rem; display: grid; gap: .2rem; border-radius: 16px; background: #F2F8F3; }.summary b { font: 700 1.8rem Lora,serif; }.summary span { color: #52705D; font-size: .8rem; font-weight: 700; }.summary .correct b { color: #2E9E62; }.summary .incorrect b { color: #D95D55; }.summary .unanswered b { color: #D99335; }.summary .time b { color: #1F5B45; font-size: 1.35rem; }.review-heading { margin-bottom: 1.2rem; display: flex; align-items: end; justify-content: space-between; gap: 1rem; }.review h2 { font-size: 2rem; }.new-quiz { padding: .7rem 1rem; border: 0; border-radius: 999px; color: #fff; background: #1F5B45; font-weight: 800; cursor: pointer; white-space: nowrap; }.answer-card { margin-bottom: .8rem; overflow: hidden; border: 1px solid #D8E7DC; border-left: 5px solid #A8C7B4; border-radius: 16px; background: #fff; }.answer-card.correct { border-left-color: #2E9E62; }.answer-card.incorrect { border-left-color: #D95D55; }.answer-card.unanswered { border-left-color: #D99335; }.answer-top { width: 100%; padding: 1.15rem; display: grid; grid-template-columns: 30px 1fr auto 24px; gap: .8rem; align-items: center; border: 0; color: #22302A; background: transparent; text-align: left; cursor: pointer; }.number { display: grid; place-items: center; width: 29px; height: 29px; border-radius: 50%; color: #1F5B45; background: #E7F3EA; font-size: .8rem; font-weight: 800; }.prompt { font: 600 1rem/1.4 Lora,serif; }.badge { padding: .3rem .5rem; border-radius: 99px; color: #52705D; background: #F2F8F3; font-size: .7rem; font-weight: 800; }.correct .badge { color: #207347; background: #E6F6EC; }.incorrect .badge { color: #A73D37; background: #FCEBE9; }.unanswered .badge { color: #9B691D; background: #FFF4D9; }.chevron { color: #52705D; font-size: 1.2rem; }.answer-detail { padding: 0 1.15rem 1.3rem; display: grid; grid-template-columns: auto auto; gap: 1.15rem 2.5rem; }.metric { display: grid; gap: .2rem; color: #52705D; font-size: .75rem; }.metric strong { color: #1F5B45; }.detail-grid { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }.detail-grid > div { padding: .9rem; border-radius: 12px; background: #F2F8F3; }.detail-grid span { color: #52705D; font-size: .72rem; font-weight: 800; }.detail-grid p { margin-top: .4rem; color: #22302A; line-height: 1.45; }.feedback { grid-column: 1 / -1; padding: .9rem; display: flex; gap: .6rem; border-radius: 12px; color: #347158; background: #E7F3EA; line-height: 1.45; }.feedback span { font-size: 1.2rem; }.dark .result-hero,.dark .feedback { background: #18382B; }.dark .result-hero h1,.dark .review h2,.dark .score,.dark .metric strong { color: #BEE0C9; }.dark .result-hero p:not(.eyebrow),.dark .summary span,.dark .metric,.dark .detail-grid span { color: #B8D4C1; }.dark .score { background: #10251C; border-color: #356447; border-top-color: #BEE0C9; }.dark .summary article,.dark .detail-grid > div { background: #122C20; }.dark .answer-card { border-color: #29503B; background: #18382B; }.dark .answer-top,.dark .detail-grid p { color: #EAF3EC; }.dark .number { color: #BEE0C9; background: #29503B; }.dark .badge { background: #29503B; color: #B8D4C1; }@media(max-width:720px) { .result-page { padding-top: 2rem; }.result-hero { align-items: start; flex-direction: column; }.score { width: 125px; height: 125px; }.summary { grid-template-columns: 1fr 1fr; margin-bottom: 3.5rem; }.review-heading { align-items: start; flex-direction: column; }.new-quiz { width: 100%; }.answer-top { grid-template-columns: 30px 1fr 20px; }.badge { grid-column: 2; justify-self: start; }.detail-grid { grid-template-columns: 1fr; } }
</style>
